script:
frappe.ui.form.on('Interview', {
    refresh: function(frm) {
        // Auto set default Interview Round on form load
        if (!frm.doc.interview_round) {
            frappe.db.get_list('Interview Round', {
                fields: ['name'],
                limit: 1
            }).then(records => {
                if (records.length > 0) {
                    frm.set_value('interview_type', records[0].name);
                }
            });
        }
    }
});

frappe.ui.form.on('Interview', {
    refresh: function(frm) {

        frm.page.set_primary_action(__('Email'), function() {

            frappe.db.get_value('Job Applicant', frm.doc.job_applicant, 'email_id')
                .then(r => {

                    let email = r.message.email_id;

                    frappe.views.CommunicationComposer({
                        doc: frm.doc,
                        frm: frm,
                        recipients: email,   // 👈 FILLED HERE
                        subject: `Interview: ${frm.doc.name}`
                    });

                });

        });

    }
});

frappe.ui.form.on('Job Applicant', {
    refresh: function(frm) {

        if (!frm.doc.__islocal) {

            frm.add_custom_button(__('Feedback'), function() {

                frappe.new_doc('Feedback', {
                    candidate_name: frm.doc.name   // ✅ THIS IS KEY
                });

            });

        }
    }
});

frappe.ui.form.on('Employee', {
    refresh: function(frm) {
        if (frappe.session.user === frm.doc.user_id) {
            frm.set_df_property('ctc', 'read_only', 1);
        } else {
            frm.set_df_property('ctc', 'read_only', 0);
        }
    }
});

frappe.ui.form.on('Job Applicant', {
    refresh: function(frm) {

        if (!frm.doc.name) return;

        let html = "<div style='padding:10px'>";

        let added_files = new Set();

        // ✅ 1. Get files from Attach fields (direct fields)
        frm.meta.fields.forEach(field => {
            if (field.fieldtype === "Attach" || field.fieldtype === "Attach Image") {

                let file_url = frm.doc[field.fieldname];

                if (file_url) {
                    let file_name = file_url.split("/").pop();

                    added_files.add(file_url);

                    html += `
                        <div style="margin-bottom:10px; padding:8px; border:1px solid #eee; border-radius:6px">
                            <b>${field.label}</b><br>
                            📄 <a href="${file_url}" target="_blank">${file_name}</a>
                        </div>
                    `;
                }
            }
        });

        // ✅ 2. Get ALL files from File DocType
        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "File",
                filters: {
                    attached_to_doctype: "Job Applicant",
                    attached_to_name: frm.doc.name
                },
                fields: ["file_name", "file_url"]
            },
            callback: function(r) {

                if (r.message.length) {

                    html += `<h5 style="margin-top:15px">Other Uploaded Files</h5>`;

                    r.message.forEach(file => {

                        // ❌ avoid duplicates (already shown from fields)
                        if (!added_files.has(file.file_url)) {

                            html += `
                                <div style="margin-bottom:6px">
                                    📎 <a href="${file.file_url}" target="_blank">
                                        ${file.file_name}
                                    </a>
                                </div>
                            `;
                        }
                    });
                }

                html += "</div>";

                frm.fields_dict.uploaded_documents.$wrapper.html(html);
            }
        });

    }
});

frappe.ui.form.on('Email Campaign', {
    refresh: function(frm) {
        frm.add_custom_button('Send Bulk Email', () => {
            frappe.call({
                method: 'hrms.api.api.send_bulk_email',
                args: {
                    docname: frm.doc.name
                },
                callback: function(r) {
                    frappe.msgprint(r.message || 'Done');
                }
            });
        });
    }
});

frappe.listview_settings['Job Applicant'] = {
    onload: function(listview) {
        listview.page.add_action_item('Send Bulk Email', function() {

            let selected = listview.get_checked_items();

            if (!selected.length) {
                frappe.msgprint("Please select applicants");
                return;
            }

            let applicant_emails = selected
                .map(d => d.email_id)
                .filter(e => e);

            if (!applicant_emails.length) {
                frappe.msgprint("No email found");
                return;
            }

            // 🔥 Fetch actual email of current user
            frappe.db.get_value('User', frappe.session.user, 'email')
                .then(r => {

                    let current_user_email = r.message.email;

                    if (!current_user_email) {
                        frappe.msgprint("Current user email not found");
                        return;
                    }

                    new frappe.views.CommunicationComposer({
                        subject: "Regarding Your Application",
                        recipients: current_user_email,   // TO = current user email
                        bcc: applicant_emails.join(","),  // BCC = applicants
                        message: "",
                        doc: null
                    });

                });

        });
    }
};

frappe.listview_settings['Lead'] = {

    refresh: function(listview) {

        const applyColors = () => {

            document.querySelectorAll('.list-row-container')
            .forEach((el)=>{

                let status =
                    el.querySelector('.indicator-pill')?.innerText || '';

                // smooth UI
                el.style.transition = 'all .2s ease';
                el.style.borderRadius = '10px';
                el.style.marginBottom = '6px';

                // LEAD
                if(status.includes('Lead')){
                    el.style.background =
                        'linear-gradient(90deg,#fff3cd,#ffe8a1)';
                    el.style.borderLeft = '6px solid orange';
                }

                // OPEN
                else if(status.includes('Open')){
                    el.style.background =
                        'linear-gradient(90deg,#d4edda,#b7f0c2)';
                    el.style.borderLeft = '6px solid green';
                }

                // OPPORTUNITY
                else if(status.includes('Opportunity')){
                    el.style.background =
                        'linear-gradient(90deg,#d1ecf1,#9fe8ff)';
                    el.style.borderLeft = '6px solid blue';
                }

            });

        };

        // instant render
        requestAnimationFrame(applyColors);

    }
};
